const data = $json;
const phone = data.phone || '';
const tenant_id = data.tenant_id || '';
const lead_name = data.lead_name || 'Sem nome';
const lead_status = data.lead_status || 'qualified';
const lead_score = data.lead_score || 3;

// Parse metadata com fallback seguro
let metadata = {};
try {
  metadata = JSON.parse(data.metadata_json || '{}');
} catch (e) {
  metadata = {};
}

const resumo = {
  titulo: `Lead Quente: ${lead_name}`,
  telefone: phone,
  nome: lead_name,
  status: lead_status,
  score: lead_score,
  objetivo: metadata.objetivo || 'Nao informado',
  faixa_valor: metadata.faixa_valor || 'Nao informado',
  bairro_interesse: metadata.bairro_interesse || 'Nao informado',
  imovel_ref: metadata.imovel_ref || null,
  localizacao_visita: metadata.localizacao_visita || null,
  data_handoff: new Date().toISOString()
};

const mensagem_texto = [
  'LEAD QUENTE - HANDOFF CORRETOR',
  `Nome: ${resumo.nome}`,
  `Telefone: ${resumo.telefone}`,
  `Objetivo: ${resumo.objetivo}`,
  `Faixa de Valor: ${resumo.faixa_valor}`,
  `Bairro: ${resumo.bairro_interesse}`,
  `Imovel Ref: ${resumo.imovel_ref || 'Nenhum'}`,
  `Local Visita: ${resumo.localizacao_visita || 'Nao definido'}`,
  `Data: ${resumo.data_handoff}`
].join('\n');

return [{
  json: {
    resumo,
    mensagem_texto,
    phone,
    tenant_id
  }
}];
